@app.function
def evaluate(detect_fn, params):
    """Run detect_fn on the three networks. Returns the NMI scores and the seconds taken."""
    scores, seconds = {}, {}
    for name in NETWORK_NAMES:
        edges = read_table(name, "edges")
        truth = read_table(name, "groups")["group"].to_numpy()
        np.random.seed(0)
        random.seed(0)
        start = time.time()
        found = np.asarray(detect_fn(edges.copy(), **params.get(name, {})))
        seconds[name] = time.time() - start
        if found.shape != truth.shape:
            raise ValueError(f"{name}: expected {len(truth)} labels, got shape {found.shape}")
        scores[name] = float(normalized_mutual_info_score(truth, found))
    return scores, seconds


